const body = $('Webhook - Foto Çözüm Talebi').first().json.body;
const ders = body.ders && body.ders !== 'Otomatik' ? body.ders : null;

const systemPrompt = "Sen Solvi tarzında çalışan bir YKS yapay zeka öğretmenisin. Sana gelen soruyu (fotoğraf ya da metin) adım adım, videoda anlatır gibi kısa ve net cümlelerle çözüyorsun. Her adım tek başına sesli okunduğunda anlaşılır olmalı. Her zaman geçerli JSON döndür.";

const userTextParts = [];
userTextParts.push({
  type: 'text',
  text: `Bu soruyu ${ders ? ders + ' dersi kapsamında' : 'dersi kendin tespit ederek'} adım adım çöz.\n${body.metin ? 'Soru metni: ' + body.metin : ''}\n\nJSON formatında yanıt ver:\n{\n  \"ders\": \"...\",\n  \"konu\": \"...\",\n  \"steps\": [\"adım 1\", \"adım 2\", \"adım 3\", \"adım 4\"],\n  \"answer\": \"...\",\n  \"tags\": [\"...\", \"...\"]\n}\n\nHer adım en fazla 2 cümle olsun, sesli anlatıma uygun, sade Türkçe kullan.`
});
if (body.gorsel) {
  userTextParts.push({ type: 'image_url', image_url: { url: body.gorsel } });
}

return [{ json: { systemPrompt, userContent: userTextParts, ders_input: ders, kullanici_id: body.kullanici_id } }];

const response = $input.first().json;
const content = response.choices[0].message.content;
let sol;
try {
  sol = JSON.parse(content);
} catch(e) {
  throw new Error('GPT yanıtı JSON parse edilemedi: ' + content);
}

const kullanici_id = $('Prompt Oluştur').first().json.kullanici_id;

return [{
  json: {
    ders: sol.ders,
    konu: sol.konu,
    steps: sol.steps,
    answer: sol.answer,
    tags: sol.tags || [],
    kullanici_id: kullanici_id,
    olusturulma_tarihi: new Date().toISOString()
  }
}];

